package com.brasa.restaurant.model;import jakarta.persistence.*;import java.math.BigDecimal;@Entity@Table(name="itens_pedido")public class ItemPedido extends BaseEntity{@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="pedido_id",nullable=false)private Pedido pedido;private String produtoId;private String nomeProduto;private int quantidade;private BigDecimal precoUnitario;private String observacao;public void setPedido(Pedido v){pedido=v;}public String getProdutoId(){return produtoId;}public void setProdutoId(String v){produtoId=v;}public String getNomeProduto(){return nomeProduto;}public void setNomeProduto(String v){nomeProduto=v;}public int getQuantidade(){return quantidade;}public void setQuantidade(int v){quantidade=v;}public BigDecimal getPrecoUnitario(){return precoUnitario;}public void setPrecoUnitario(BigDecimal v){precoUnitario=v;}public String getObservacao(){return observacao;}public void setObservacao(String v){observacao=v;}}
